-- ============================================================================
-- 图书管理系统 · 种子数据脚本
-- ============================================================================
-- 版本  : v2.0
-- 前置  : 必须先执行 schema.sql（本脚本不做任何 DDL，需在空表上执行）
-- 用法  : mysql -uroot -p < data.sql
--
-- 数据量（17 张表，共 398 行）
--   t_department 2      · t_major 5           · t_class 12
--   t_student 43        · t_teacher 6         · t_admin 1
--   t_category 7        · t_book 47           · t_book_copy 127
--   t_borrow_config 5   · t_borrow_record 51  · t_fine 12
--   t_banner 8          · t_comment 37        · t_recommend 18
--   t_notification 15   · t_holiday_config 2
--
-- 数据约定（合并自一次性脚本，结果已固化在本文件中）
--   · t_book.create_time：30 本为 2026-04-10（旧书），16 本为 2026-07-03、
--     1 本为 2026-07-08（新书）。用于验证「新书上架 30 天内」的借阅上限规则
--     —— 原 update-book-time.sql 的 ORDER BY RAND() 结果已固化，不再随机
--   · t_borrow_record.status：含 4 条 4=待审核（原 update-borrow-status.sql 的结果）
--   · 含 2 条超期记录（用户 id=8，原 test-overdue-data.sql 的结果）
--   · 封面 / 轮播图 URL 统一为 http://localhost:9000（本地 MinIO）。
--     部署到其它主机时改 minio.endpoint 环境变量，或对 t_book.cover_url、
--     t_banner.image_url 批量 REPLACE —— 原 update-minio-url.sql 的换址动作
--     属于环境迁移，不属于种子数据，故未写入
--   · 全部密码为 BCrypt 哈希，明文统一为 123456
--
-- 变更记录
--   v2.0 2026-11  整理为单一数据脚本：
--                 ① 去掉 mysqldump 的 LOCK TABLES / UNLOCK TABLES（需要额外权限，
--                    且一致性由下面的单个事务保证）
--                 ② 整段包进事务并关闭外键检查，保证按任意表顺序插入都能成功
--                 ③ 补充各表数据量与原脚本的对应关系
--   v1.0          mysqldump 导出的初始数据
-- ============================================================================

CREATE DATABASE IF NOT EXISTS `book_management`
  DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `book_management`;

SET NAMES utf8mb4;
SET SESSION FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;

