INSERT INTO `t_class` (`id`, `name`, `major_id`) VALUES (1,'软件2411',1),(2,'软件2412',1),(3,'计科2411',2),(4,'计科2412',2),(5,'智能2411',3),(6,'智能2412',3),(7,'软件硕2411',1),(8,'软件博2411',1),(9,'数学2411',4),(10,'数学2412',4),(11,'物理2411',5),(12,'物理2412',5);
INSERT INTO `t_comment` (`id`, `book_id`, `user_id`, `rating`, `content`, `create_time`, `update_time`) VALUES (1,1,8,5,'内容非常详实，Java SE 覆盖得很全面，尤其是泛型和集合那几章讲得特别好。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(2,1,28,4,'经典就是经典，但实在太厚了，每天背来背去挺锻炼身体的。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(3,1,30,5,'工作中必备的参考书，遇到问题翻一翻基本都能找到答案。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(4,3,30,5,'每个 Java 开发者都应该读的一本书，90 条建议条条经典。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(5,3,16,4,'内容很好，但需要有实战经验才能完全理解，不建议初学者。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(6,5,8,5,'零基础入门首选！项目实战部分设计得很好，跟着做完特别有成就感。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(7,5,24,4,'例子很清晰，但项目部分如果能更多涉及实际开发场景就更好了。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(8,5,35,5,'终于有一本书能让我这个数学专业的人学会编程了，非常推荐。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(9,9,28,4,'谢老师的教材条理清晰，配合网课学效果翻倍。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(10,9,31,5,'写得很好，理论与实践结合得不错。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(11,10,8,5,'邓老师写的数据结构教材非常好，代码实现规范，配套 MOOC 课也很赞。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(12,10,24,3,'内容不错但 C++ 版对初学者不太友好，建议先学完 C++ 再看。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(13,12,30,4,'CLRS 算法圣经，主要当参考书用，从头啃确实需要毅力。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(14,12,33,5,'做算法竞赛必备，虽然很厚但每章都有收获。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(15,18,30,5,'深度学习圣经，数学推导详细，读完后对神经网络理解上升了一个层次。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(16,18,33,4,'很好但很硬核，建议有机器学习基础再读。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(17,19,24,5,'周老师的西瓜书深入浅出，配合南瓜书看效果更佳。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(18,19,30,4,'理论推导清晰，但代码实现部分偏少，需要配合实战书。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(19,33,20,5,'太震撼了！大刘的想象力让人叹为观止，黑暗森林法则细思极恐。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(20,33,35,5,'中国科幻的巅峰之作，读完再看星空，感觉都不一样了。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(21,34,20,5,'面壁者和破壁人的博弈精彩绝伦，逻辑推演极强。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(22,35,20,5,'二向箔的名场面我现在都还记得，宇宙尺度的浪漫与残酷并存。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(23,32,31,5,'余华用最平静的文字写了最沉重的人生，强烈推荐。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(24,32,37,4,'看一次哭一次，人是为了活着本身而活着的。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(25,26,35,4,'同济高数 yyds，考研全靠它打基础。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(26,26,37,3,'教材质量没话说，但高数是真的难（笑）。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(27,28,35,4,'同济版线代编排很好，从线性方程组引入矩阵，比直接讲矩阵更容易理解。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(28,38,37,5,'曼昆的经济学原理太适合入门了，案例生动有趣。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(29,38,39,4,'读完对日常生活中的经济现象有了全新认识。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(30,40,39,4,'垄断与竞争那章是全书精华，篇幅不长但值得反复读。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(31,42,39,5,'卡尼曼让我意识到人类决策中有多少认知偏差，对学习和生活都很有启发。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(32,36,42,5,'钱钟书的讽刺艺术登峰造极，常读常新。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(33,37,42,4,'魔幻现实主义名不虚传，但人名真的太难记了……需要画族谱。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(34,7,16,4,'Go 的并发模型讲得很清楚，goroutine 和 channel 的设计确实优雅。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(35,17,16,5,'CSAPP 是计科学生必读书，读过之后对计算机的理解完全不一样了。','2026-07-03 16:42:08','2026-07-03 16:42:08'),(36,46,8,5,'test','2026-07-06 11:43:51','2026-07-06 11:43:51'),(37,29,8,5,'1','2026-07-06 12:20:37','2026-07-06 12:20:37');
